glsl3.vert:
precision highp float;
in vec3 a_position;
vec4 vert () {
  return vec4(a_position.xy, 0.0, 1.0);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
uniform sampler2D bgTex;
uniform sampler2D compTex;
uniform sampler2D fxTex;
layout(std140) uniform ScreenConstants {
  vec4 sInv;
  vec4 sShift;
  vec4 sRect;
  vec4 fxRect;
  vec4 fl;
  vec4 flView;
  vec4 flColor;
};
bool inside (vec2 p, vec4 r) { return p.x >= r.x && p.x <= r.z && p.y >= r.y && p.y <= r.w; }
vec4 frag () {
  vec2 uv = gl_FragCoord.xy * sInv.xy;
  vec3 col = texture(bgTex, uv).rgb;
  if (inside(uv, sRect)) {
    vec2 u = uv - sShift.xy, o = sInv.zw;
    vec4 c = 0.25 * (texture(compTex, u + vec2(-o.x, -o.y)) + texture(compTex, u + vec2(o.x, -o.y))
                   + texture(compTex, u + vec2(-o.x, o.y)) + texture(compTex, u + vec2(o.x, o.y)));
    col = c.rgb + col * (1.0 - c.a);
  }
  if (inside(uv, fxRect)) {
    vec4 f = texture(fxTex, uv);
    col = f.rgb + col * (1.0 - f.a);
  }
  if (fl.w > 0.003) {
    vec2 p = vec2(gl_FragCoord.x, flView.x - gl_FragCoord.y) / flView.y;
    float r = length(p - fl.xy) / max(fl.z, 1.0);
    vec3 w = vec3(1.0);
    vec4 c;
    if (r < 0.07) c = mix(vec4(w, 0.95), vec4(w, 0.7), r / 0.07);
    else if (r < 0.22) c = mix(vec4(w, 0.7), vec4(flColor.rgb, 0.6), (r - 0.07) / 0.15);
    else if (r < 0.42) c = mix(vec4(flColor.rgb, 0.6), vec4(flColor.rgb, 0.14), (r - 0.22) / 0.2);
    else if (r < 0.62) c = mix(vec4(flColor.rgb, 0.14), vec4(flColor.rgb, 0.0), (r - 0.42) / 0.2);
    else c = vec4(0.0);
    vec3 s = c.rgb * (c.a * fl.w);
    col = col + s - col * s;
  }
  return vec4(col, 1.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

